from helpers import D, src, DSM, mk
from functools import partial
CARDS = []
S = partial(mk, "sleep", "sleep", "moon")
AASM = src("src-aasm-insomnia", "Behavioral and psychological treatments for chronic insomnia disorder in adults: an AASM clinical practice guideline", "American Academy of Sleep Medicine", "https://aasm.org/new-guideline-supports-behavioral-psychological-treatments-for-insomnia/", 2021, seen=True)
NHS_SLEEP = src("src-nhs-insomnia", "Insomnia", "NHS", "https://www.nhs.uk/conditions/insomnia/", note="Not opened.")
EURO = src("src-euro-sleep", "Prevalence of sleep disorders in the adult population (European estimate summary)", "Secondary summary of a 2026 European analysis", "https://www.vol.at/so-many-europeans-suffer-from-sleep-disorders/9991844", 2026, seen=True, note="Secondary source; replace with the primary analysis.")
DSM_S = DSM("Sleep-Wake Disorders")

CARDS.append(S("insomnia-disorder", "Insomnia Disorder", "When sleep won't come, or won't stay", ["chronic insomnia", "sleeplessness"], "F51.01",
 "Trouble falling or staying asleep, or waking too early, three nights a week for three months or more.",
 "Everyone has bad nights. Insomnia disorder is when they become the pattern: lying awake for ages, waking in the night and not getting back off, or waking far too early, several nights a week for months, with tiredness, low mood, and poor concentration by day. It often starts with stress and then gets kept going by worry about sleep itself and by habits that make sense but backfire. It's very common, and the best treatment isn't a pill.",
 ["Bedtime became the scariest part of the day. The more I tried, the less I slept.", "I'd lie there doing maths about how many hours I had left.", "CBT for insomnia felt counterintuitive. Less time in bed, more sleep. It worked in six weeks."],
 ["Taking a long time to fall asleep, or waking and not getting back to sleep", "Waking much earlier than planned", "At least three nights a week for three months or more", "Tiredness, irritability, low mood, or poor concentration by day", "Worrying about sleep and dreading bedtime", "Happening even when there's enough time and a decent place to sleep"],
 [{"myth": "Everyone needs eight hours.", "fact": "Sleep needs vary. The problem in insomnia is distress and daytime effects, not a number."},
  {"myth": "Sleeping tablets are the answer.", "fact": "They help short-term but lose effect, cause dependence, and don't fix the pattern. CBT for insomnia works better and lasts."},
  {"myth": "Lying in bed resting is almost as good as sleep.", "fact": "Lying awake in bed teaches the brain that bed means wakefulness. Getting up until sleepy is part of the cure."}],
 {"plain": "About 1 in 10 adults has insomnia disorder, and many more have occasional sleep trouble. Women and older adults are affected more often.", "figure": "About 10% of adults (European population estimate); higher rates with broader definitions", "source_ref": "src-euro-sleep"},
 {"plain_summary": "Cognitive behavioural therapy for insomnia (CBT-I) is the recommended first treatment and works for most people in four to eight sessions, in person, online, or through apps. It resets the link between bed and sleep, tightens the sleep window, and calms worry about sleep. Medication, prescribed and monitored by a doctor, is for short-term use or when CBT-I isn't enough. Treating depression, anxiety, pain, or sleep apnoea often improves insomnia too.",
  "evidence_based_options": ["CBT for insomnia (CBT-I), including digital versions", "Treating co-occurring conditions such as depression, anxiety, pain, or sleep apnoea", "Short-term medication in some cases, prescribed and monitored by a doctor", "Sleep-restriction and stimulus-control techniques within CBT-I"],
  "self_help_that_supports_care": ["Same wake time every day, even after a bad night", "Getting up if awake for more than 20 minutes and returning when sleepy", "No clock-watching, and bed only for sleep and sex", "Daylight in the morning, less caffeine and alcohol in the evening"],
  "guideline_refs": ["src-aasm-insomnia"]},
 "If poor sleep has gone on for a month or more and is affecting your days, ask a doctor about CBT for insomnia. Mention snoring, restless legs, or low mood too, as they change the plan.",
 "A few bad nights during stress, jet lag, shift work, or a new baby aren't insomnia disorder. Sleep trouble caused mainly by sleep apnoea, restless legs, or a body-clock problem is treated differently.",
 "Insomnia is one of the most treatable sleep conditions. Most people who complete CBT-I sleep better within weeks and keep the gains.",
 ["circadian-rhythm-sleep-wake-disorders", "breathing-related-sleep-disorders", "restless-legs-syndrome", "generalized-anxiety-disorder", "major-depressive-disorder", "sedative-hypnotic-anxiolytic-use-disorder"],
 ["cbt-i", "sleep-hygiene", "sleep-medication", "circadian-rhythm", "rumination", "revenge-bedtime-procrastination"],
 ["reddit-r-insomnia", "sleep-disorders-australia"],
 ("Soft line illustration of a person reading in a dim armchair at night with a small lamp, bedroom door open to a calm dark bed, a clock turned to face the wall. Pastel indigo and cream.", "A person reads in a dim armchair at night, a clock turned to the wall, a calm bedroom visible beyond."),
 [DSM_S, AASM, NHS_SLEEP, EURO], qs=["Replace the secondary prevalence source with a primary one.", "Add a verified UK/US insomnia community."],
 young="Teenagers' body clocks run late, so 'insomnia' at 11pm is often biology plus screens. CBT-I works for teens; for younger children, behavioural approaches with parents are used.",
 cult="Sleep norms differ: co-sleeping, siestas, late dinners, and prayer schedules all shape what's normal. Night-shift and gig work push insomnia rates up in many communities.",
 subs=[{"title": "Other specified and unspecified insomnia disorder", "icd10cm_code": "G47.09 / G47.00", "text": "Used for insomnia that doesn't yet meet the full pattern, for example shorter than three months."}]))

CARDS.append(S("hypersomnolence-disorder", "Hypersomnolence Disorder", "Sleeping plenty and still exhausted", ["idiopathic hypersomnia (related)", "excessive daytime sleepiness"], "F51.11",
 "Being very sleepy during the day despite sleeping at least seven hours, for months, with no other cause found.",
 "Hypersomnolence disorder is more than feeling tired. A person sleeps a full night, often longer, and still fights to stay awake by day, falls asleep unintentionally, takes long naps that don't refresh, or struggles to wake up at all ('sleep drunkenness'). It goes on for three months or more and isn't explained by poor sleep, apnoea, medication, or another condition. It's often dismissed as laziness. It's a real neurological condition, and there is treatment.",
 ["I slept ten hours and still couldn't keep my eyes open in meetings. People thought I was bored.", "Waking up felt like climbing out of wet concrete, every single day.", "The sleep study was the first time anyone believed me."],
 ["Sleeping seven hours or more and still very sleepy by day", "Falling asleep unintentionally, or long naps that don't refresh", "Great difficulty waking, feeling confused or clumsy for a while after", "At least three times a week for three months or more", "Daytime life affected: work, driving, relationships", "No other explanation, like apnoea, medication, or not enough sleep"],
 [{"myth": "Sleeping a lot means you're lazy or depressed.", "fact": "Hypersomnolence is a neurological disorder. Depression can cause oversleeping too, which is why a proper assessment matters."},
  {"myth": "Just get more sleep.", "fact": "People with hypersomnolence already sleep plenty. More sleep doesn't help; treatment does."},
  {"myth": "It's the same as narcolepsy.", "fact": "They're related but different. Narcolepsy has sudden sleep attacks and often cataplexy; hypersomnolence is constant sleepiness and long sleep."}],
 {"plain": "Hypersomnolence disorder is uncommon in the general population but makes up a meaningful share of people seen in sleep clinics.", "figure": "DSM-5-TR text: about 1% of the general population report sleep drunkenness; around 5–10% of sleep-clinic patients with daytime sleepiness are diagnosed with hypersomnolence disorder", "source_ref": "src-dsm", "note": "Figures from the DSM-5-TR text; need primary sources."},
 {"plain_summary": "Diagnosis needs a sleep study to rule out apnoea and narcolepsy. Treatment usually combines wake-promoting medication, prescribed and monitored by a sleep specialist, with planned naps and a regular schedule. Treating any depression or other conditions helps. Driving safety is discussed as part of care.",
  "evidence_based_options": ["Sleep study and specialist assessment", "Wake-promoting medication, prescribed and monitored by a sleep specialist", "Scheduled naps and a strict regular sleep-wake schedule", "Treatment of co-occurring depression or other conditions"],
  "self_help_that_supports_care": ["Keeping a sleep diary for two weeks before the appointment", "Planning short naps rather than fighting through", "Alarms, light, and a routine for the hard morning window", "Not driving when sleepy, and talking to a doctor about driving rules"],
  "guideline_refs": ["src-aasm-hypersomnia"]},
 "If you sleep well but still can't stay awake by day for months, ask a doctor for a referral to a sleep clinic. Do not drive if you feel sleepy; tell your doctor so the risk can be managed.",
 "Being tired because of not enough sleep, shift work, medication, or a medical illness isn't hypersomnolence disorder. Sleep apnoea and narcolepsy cause daytime sleepiness too and need their own tests.",
 "With a diagnosis and the right treatment, people with hypersomnolence get their days back.",
 ["narcolepsy", "breathing-related-sleep-disorders", "major-depressive-disorder", "circadian-rhythm-sleep-wake-disorders"],
 ["cataplexy", "circadian-rhythm", "assessment"],
 ["narcolepsy-network", "hypersomnia-foundation", "reddit-r-narcolepsy", "sleep-disorders-australia"],
 ("Soft line illustration of a person at a sunny kitchen table with a sleep diary, an alarm clock, and a bright window, a cat asleep nearby. Pastel indigo and yellow.", "A person sits at a sunny kitchen table with a sleep diary and an alarm clock while a cat sleeps nearby."),
 [DSM_S, src("src-aasm-hypersomnia", "Treatment of central disorders of hypersomnolence: an AASM clinical practice guideline", "American Academy of Sleep Medicine", "https://aasm.org/clinical-resources/practice-standards/practice-guidelines/", 2021, note="Not opened; guideline listing URL."), src("src-hf", "Hypersomnia Foundation", "Hypersomnia Foundation", "https://www.hypersomniafoundation.org/", seen=True)],
 qs=["Find primary prevalence sources."],
 young="Hypersomnolence often starts in the late teens, when it's easily blamed on 'teenage sleep'. A sleep diary and a sleep study tell the difference.",
 subs=[{"title": "Other specified and unspecified hypersomnolence disorder", "icd10cm_code": "G47.19 / G47.10", "text": "For sleepiness that doesn't yet meet the full pattern."}]))

CARDS.append(S("narcolepsy", "Narcolepsy", "When sleep ambushes you", ["narcolepsy type 1 and type 2", "narcolepsy with or without cataplexy"], "G47.41x / G47.42x (by type)",
 "A neurological condition causing overwhelming daytime sleepiness and sudden sleep, often with cataplexy: brief muscle weakness triggered by emotion.",
 "Narcolepsy is a lifelong neurological condition where the brain can't regulate sleep and wakefulness. People feel overwhelmingly sleepy by day and can fall asleep suddenly in the middle of things. Type 1 also brings cataplexy: sudden muscle weakness when laughing, surprised, or angry, while fully awake. Sleep paralysis and vivid dream-like hallucinations at the edge of sleep are common. It usually starts in the teens and is often misdiagnosed for years. Treatment makes a big difference.",
 ["I'd fall asleep mid-sentence. Teachers thought I was being rude.", "When I laugh hard my knees go. I used to think everyone's did.", "Fifteen years to a diagnosis. Then one medication and my life came back."],
 ["Overwhelming daytime sleepiness, falling asleep suddenly, most days", "Cataplexy: brief muscle weakness when laughing, surprised, or emotional (type 1)", "Sleep paralysis on waking or falling asleep", "Vivid, dream-like hallucinations at the edge of sleep", "Disturbed night-time sleep", "Going on for three months or more"],
 [{"myth": "People with narcolepsy just collapse asleep randomly all the time.", "fact": "Sudden sleep happens, but the main experience is relentless sleepiness. Cataplexy is weakness, not sleep, and the person is awake."},
  {"myth": "It's rare and dramatic, so I'd know if I had it.", "fact": "Most people with narcolepsy wait years for a diagnosis, often being told they're lazy, depressed, or have epilepsy."},
  {"myth": "Nothing can be done.", "fact": "Medication, scheduled naps, and routine let most people with narcolepsy work, study, and live fully."}],
 {"plain": "Narcolepsy affects roughly 1 in 2,000 people. Type 1 (with cataplexy) is more common than type 2. Many people are never diagnosed.", "figure": "About 0.04%–0.05% of adults (roughly 1 in 2,000–2,500), population estimates", "source_ref": "src-euro-sleep"},
 {"plain_summary": "Diagnosis needs a sleep study with daytime nap tests, sometimes a spinal fluid test for hypocretin. Treatment combines medication, prescribed and monitored by a sleep specialist: wake-promoting drugs for sleepiness, and specific medicines for cataplexy and disturbed night sleep. Scheduled short naps, a regular schedule, and school or workplace adjustments are part of the plan. Peer support helps with the years of being misunderstood.",
  "evidence_based_options": ["Sleep study and specialist diagnosis", "Wake-promoting medication, prescribed and monitored by a sleep specialist", "Medication for cataplexy and night-time sleep, prescribed and monitored", "Scheduled naps, regular routine, and workplace or school adjustments"],
  "self_help_that_supports_care": ["Short planned naps at the same times each day", "Telling school or work and asking for adjustments", "Not driving when sleepy; discussing driving rules with your doctor", "Connecting with others with narcolepsy, who get it instantly"],
  "guideline_refs": ["src-aasm-hypersomnia"]},
 "If you fall asleep uncontrollably by day, or your muscles go weak when you laugh, ask a doctor for a sleep-clinic referral. Mention sleep paralysis and vivid hallucinations; they're common in narcolepsy and don't mean psychosis.",
 "Being very tired from poor sleep, shift work, or medication isn't narcolepsy. Sleep apnoea causes daytime sleepiness and needs its own test. Cataplexy is not fainting or a seizure.",
 "Narcolepsy is lifelong, and so is living well with it. The right diagnosis and treatment change everything.",
 ["hypersomnolence-disorder", "breathing-related-sleep-disorders", "major-depressive-disorder", "parasomnias"],
 ["cataplexy", "sleep-paralysis", "hallucination", "circadian-rhythm"],
 ["narcolepsy-network", "reddit-r-narcolepsy", "wake-up-narcolepsy-heypeers", "hypersomnia-foundation", "sleep-disorders-australia"],
 ("Soft line illustration of a young person laughing with friends on a sofa, one friend's arm casually ready behind them, a clock showing a planned nap time on the wall. Pastel indigo and coral.", "A young person laughs with friends on a sofa, a friend's arm ready behind them, a clock on the wall."),
 [DSM_S, EURO, src("src-aasm-hypersomnia", "Treatment of central disorders of hypersomnolence: an AASM clinical practice guideline", "American Academy of Sleep Medicine", "https://aasm.org/clinical-resources/practice-standards/practice-guidelines/", 2021, note="Not opened; listing URL."), src("src-nn", "Narcolepsy Network: support groups", "Narcolepsy Network", "https://narcolepsynetwork.org/resources/support-groups/", seen=True), src("src-ninds-narc", "Narcolepsy", "National Institute of Neurological Disorders and Stroke", "https://www.ninds.nih.gov/health-information/disorders/narcolepsy", note="Not opened.")],
 young="Narcolepsy usually begins between ages 10 and 20. Falling asleep in class, sudden weight gain, and 'clumsiness' from cataplexy are common first signs, and misdiagnosis as laziness, ADHD, or depression is frequent.",
 subs=[{"title": "Types", "icd10cm_code": "G47.411 / G47.419 / G47.421 / G47.429", "text": "Type 1: with cataplexy or low hypocretin. Type 2: without cataplexy and with normal hypocretin. Either can also be caused by another medical condition."}]))

CARDS.append(S("breathing-related-sleep-disorders", "Breathing-Related Sleep Disorders", "Sleep apnoea and breathing problems in sleep", ["obstructive sleep apnoea", "OSA", "central sleep apnoea", "sleep-related hypoventilation"], "G47.3x",
 "Breathing that repeatedly stops, pauses, or becomes too shallow during sleep, breaking sleep and causing daytime exhaustion.",
 "In obstructive sleep apnoea, the airway narrows or closes during sleep, so breathing stops for seconds at a time, many times an hour, and the brain briefly wakes to restart it. People rarely remember, but they wake unrefreshed, snore loudly, and feel exhausted and foggy by day. Untreated, it raises blood pressure, heart, and accident risk. Central sleep apnoea and hypoventilation are rarer forms where the brain's breathing drive is the issue. All are very treatable.",
 ["My partner said I stopped breathing in the night. I thought she was exaggerating.", "I fell asleep at a red light. That's when I finally went to the doctor.", "The CPAP machine took a few weeks to get used to. Now I can't believe how I used to feel."],
 ["Loud snoring, gasping, or choking in sleep, often noticed by someone else", "Pauses in breathing during sleep", "Waking unrefreshed, with a dry mouth or headache", "Severe daytime sleepiness, falling asleep when sitting still", "Poor concentration, irritability, low mood", "High blood pressure, or waking to pass urine at night"],
 [{"myth": "Only overweight older men get sleep apnoea.", "fact": "It's more common with weight and age, but it affects women, slim people, and children too, and is under-diagnosed in women."},
  {"myth": "Snoring is harmless.", "fact": "Loud snoring with pauses or gasping is a warning sign. Untreated apnoea raises heart and stroke risk."},
  {"myth": "CPAP is unbearable.", "fact": "Modern machines are quiet and masks come in many styles. Most people adapt within weeks and feel dramatically better."}],
 {"plain": "Obstructive sleep apnoea is common: estimates range from a few percent of adults to one in five or more, depending on how it's measured. Most people with it don't know.", "figure": "About 2%–15% of middle-aged adults (DSM-5-TR text); up to around 18% in some population estimates", "source_ref": "src-euro-sleep"},
 {"plain_summary": "A sleep study (often done at home) confirms the diagnosis. For obstructive apnoea, CPAP, a machine that gently keeps the airway open with air pressure, is the main treatment and works very well. Alternatives include dental devices, positional therapy, weight management, and sometimes surgery. Central apnoea and hypoventilation need specialist assessment and different breathing support. Treating apnoea often lifts mood, blood pressure, and energy.",
  "evidence_based_options": ["Home or lab sleep study", "CPAP therapy for obstructive sleep apnoea", "Oral appliances, positional therapy, and weight management where appropriate", "Specialist breathing support for central apnoea and hypoventilation"],
  "self_help_that_supports_care": ["Asking a bed partner about snoring and pauses", "Sleeping on your side; avoiding alcohol and sedatives before bed", "Sticking with CPAP through the adjustment period and asking for a different mask if needed", "Peer support for CPAP users"],
  "guideline_refs": ["src-nhs-osa"]},
 "If you snore loudly, stop breathing in sleep, or are very sleepy by day, ask a doctor for a sleep assessment. Don't drive if sleepy. Mention mood and memory changes too; they often improve with treatment.",
 "Simple snoring without pauses or daytime sleepiness isn't a disorder, though it's worth mentioning. Insomnia and narcolepsy cause sleep problems by different mechanisms.",
 "Treating sleep apnoea is one of the biggest quality-of-life improvements in medicine. People describe waking up for the first time in years.",
 ["insomnia-disorder", "hypersomnolence-disorder", "major-depressive-disorder", "major-and-mild-neurocognitive-disorder"],
 ["sleep-hygiene", "circadian-rhythm", "brain-fog"],
 ["reddit-r-sleepapnea", "hope2sleep-uk", "sleep-disorders-australia"],
 ("Soft line illustration of a person waking refreshed, stretching by an open window with morning light, a small bedside device with a soft blue light. Pastel indigo and sky blue.", "A person stretches by an open window in morning light, a small bedside device glowing softly."),
 [DSM_S, EURO, src("src-nhs-osa", "Sleep apnoea", "NHS", "https://www.nhs.uk/conditions/sleep-apnoea/", note="Not opened."), src("src-hope2sleep", "Hope2Sleep Charity", "Hope2Sleep", "https://www.hope2sleep.co.uk/", seen=True, note="Seen via a donation listing; main site not opened.")],
 young="Children with sleep apnoea often have large tonsils, snore, breathe through the mouth, and show it as hyperactivity, poor concentration, or bedwetting rather than sleepiness. Removing tonsils and adenoids is often the treatment.",
 cult="Apnoea is under-diagnosed in women and in some ethnic groups because the 'typical patient' stereotype is a large, older man. Access to sleep studies and CPAP varies hugely by country and income.",
 subs=[{"title": "Types", "icd10cm_code": "G47.33 / G47.31 / G47.34", "text": "Obstructive sleep apnoea hypopnea (the airway narrows); central sleep apnoea (the brain's breathing signal pauses); sleep-related hypoventilation (breathing too shallow). Each has its own causes and treatments."}]))

CARDS.append(S("circadian-rhythm-sleep-wake-disorders", "Circadian Rhythm Sleep-Wake Disorders", "When your body clock is out of step", ["delayed sleep phase", "advanced sleep phase", "shift work disorder", "non-24"], "G47.2x",
 "Sleep problems caused by a mismatch between your internal body clock and the schedule you need to keep.",
 "Your body clock decides when you feel sleepy and awake. In circadian rhythm disorders, that clock is set differently from the schedule life demands. Delayed sleep phase means you can't fall asleep until the early hours and can't wake for school or work. Advanced phase means sleeping and waking very early. Shift work and jet lag throw the clock off. In non-24, the clock drifts daily. The sleep is fine; the timing isn't, and timing can be shifted.",
 ["I'm not lazy. I physically cannot sleep before 3am. Mornings at school were torture.", "Night shifts for ten years and my body never adjusted.", "Light in the morning, melatonin in the evening, slowly. My clock moved two hours in a month."],
 ["Can't fall asleep until very late and can't wake in the morning (delayed phase)", "Falling asleep in the early evening and waking in the small hours (advanced phase)", "Sleep that's fine when allowed to follow your own timing", "Exhaustion, poor performance, and low mood from fighting the clock", "Caused or worsened by shift work, travel, or a drifting clock", "Lasting three months or more"],
 [{"myth": "Night owls just lack discipline.", "fact": "Delayed sleep phase is biological and often runs in families. Willpower doesn't move a body clock; light and timing do."},
  {"myth": "You can train yourself to need less sleep on shifts.", "fact": "Shift work disorder is real. Smart scheduling, light, and naps help, but the clock can't be 'trained' away."},
  {"myth": "Melatonin is just a sleeping pill.", "fact": "Melatonin is mainly a timing signal. Used at the right time, it shifts the clock; used randomly, it does little."}],
 {"plain": "Delayed sleep phase affects up to 1 in 6 teenagers and young adults in some studies, and shift work disorder affects a meaningful share of the millions who work nights.", "figure": "DSM-5-TR text: delayed sleep phase about 0.17% of the general population but up to 7–16% of adolescents and young adults; shift work disorder in 5–10% of night-shift workers", "source_ref": "src-dsm", "note": "Figures from the DSM-5-TR text; need primary sources."},
 {"plain_summary": "Treatment shifts the clock: timed bright light (morning for delayed phase, evening for advanced), timed low-dose melatonin, prescribed or advised by a doctor, and a gradual, consistent schedule. For shift workers, planned naps, light management, and strategic timing of sleep help. School or work flexibility, where possible, makes a big difference. CBT-I techniques help with the insomnia that builds on top.",
  "evidence_based_options": ["Timed bright light therapy", "Timed melatonin, prescribed or advised by a doctor", "Gradual schedule shifting and strict consistency", "Chronotherapy and CBT-I techniques; adjustments at school or work"],
  "self_help_that_supports_care": ["Bright light within an hour of waking; dim light and no screens late evening", "Moving bedtime and wake time by 15–30 minutes every few days, not all at once", "The same wake time every day, including weekends", "For shift work: dark glasses on the way home, blackout curtains, planned naps"],
  "guideline_refs": ["src-aasm-circadian"]},
 "If you can only sleep at the 'wrong' times and it's wrecking school, work, or mood, ask a doctor or sleep clinic about circadian rhythm treatment. Bring two weeks of a sleep diary.",
 "Preferring late nights but able to adjust when needed isn't a disorder. Insomnia (can't sleep at any time) is different from delayed phase (sleep is fine, just late).",
 "Body clocks can be moved. With light, timing, and patience, most people shift to a schedule that works.",
 ["insomnia-disorder", "hypersomnolence-disorder", "major-depressive-disorder", "bipolar-i-disorder", "adhd"],
 ["circadian-rhythm", "light-therapy", "sleep-medication", "sleep-hygiene", "cbt-i"],
 ["reddit-r-insomnia", "sleep-disorders-australia"],
 ("Soft line illustration of a person opening blinds to bright morning light with a glass of water, a wall clock and a calendar with gradually earlier times marked. Pastel indigo and gold.", "A person opens blinds to bright morning light, a calendar on the wall marked with gradually earlier times."),
 [DSM_S, src("src-aasm-circadian", "Clinical practice guideline for the treatment of intrinsic circadian rhythm sleep-wake disorders", "American Academy of Sleep Medicine", "https://aasm.org/clinical-resources/practice-standards/practice-guidelines/", 2015, note="Not opened; listing URL."), NHS_SLEEP],
 qs=["Find primary prevalence sources.", "Add a verified non-24 or delayed-phase community."],
 young="Teenagers' clocks naturally run two hours later than adults', which is why early school starts cause so much harm. Delayed sleep phase disorder goes beyond this and needs treatment, but later school times help everyone.",
 subs=[{"title": "Types", "icd10cm_code": "G47.21 / G47.22 / G47.23 / G47.24 / G47.26 / G47.20", "text": "Delayed sleep phase, advanced sleep phase, irregular sleep-wake (no clear pattern, often in dementia), non-24-hour (clock drifts daily, mostly in blind people), shift work type, and unspecified."}]))

CARDS.append(S("parasomnias", "Parasomnias (Sleepwalking, Sleep Terrors, and REM Sleep Behaviour Disorder)", "Strange things that happen during sleep", ["sleepwalking", "night terrors", "REM behaviour disorder", "RBD"], "F51.3 / F51.4 / G47.52", 
 "Unusual behaviours during sleep: walking, screaming in terror, or acting out dreams, that the person usually doesn't remember.",
 "Parasomnias are things the body does while the brain is partly asleep. In sleepwalking and sleep terrors, a person gets up, talks, screams, or moves about in deep sleep, eyes open but not awake, and remembers nothing; common in children and usually fading. In REM sleep behaviour disorder, mostly in older adults, the paralysis of dreaming sleep fails, so people act out dreams. That one needs medical attention: it can injure a partner and is linked to later neurological conditions.",
 ["My son screams in terror at midnight, eyes wide open, and has no idea in the morning. It's worse for us than for him.", "I found myself in the kitchen at 3am with no memory of getting there.", "My husband punched the wall in his sleep, dreaming about a fight. The sleep clinic took it very seriously."],
 ["Getting up and walking or doing things while asleep, hard to wake, no memory after", "Screaming and intense fear early in the night, not fully awake, no memory after", "Acting out dreams: shouting, punching, kicking, falling out of bed (REM behaviour disorder)", "Episodes causing distress, injury, or embarrassment", "In children: usually harmless and outgrown; in adults: worth assessing"],
 [{"myth": "Never wake a sleepwalker.", "fact": "Waking them won't harm them, though they may be confused. Gently guiding them back to bed is usually easiest."},
  {"myth": "Night terrors mean a child is traumatized.", "fact": "Sleep terrors are a normal feature of deep sleep in young children and are not caused by trauma. Nightmares are different."},
  {"myth": "Acting out dreams is just vivid dreaming.", "fact": "REM sleep behaviour disorder is a specific condition that needs assessment, both for safety and because of its links to Parkinson's and related conditions."}],
 {"plain": "Sleepwalking and sleep terrors are common in children and uncommon in adults. REM sleep behaviour disorder is rare, affecting well under 1 in 100 people, mostly older men.", "figure": "DSM-5-TR text: sleepwalking in 10–30% of children at some point, around 1–7% of adults; sleep terrors in up to about 40% of young children; RBD about 0.4–0.5% of the general population", "source_ref": "src-dsm", "note": "Figures from the DSM-5-TR text; need primary sources."},
 {"plain_summary": "For sleepwalking and sleep terrors in children, the main treatment is safety (locks, gates, clear floors), good sleep routines, and reassurance; they usually fade. Scheduled brief awakenings can help frequent episodes. In adults, triggers like sleep loss, alcohol, stress, and some medicines are addressed, and a sleep study rules out apnoea. REM sleep behaviour disorder needs specialist assessment, bedroom safety measures, and often medication, prescribed and monitored by a doctor, plus follow-up for neurological health.",
  "evidence_based_options": ["Safety measures and reassurance for childhood sleepwalking and terrors", "Scheduled awakenings for frequent childhood episodes", "Treating triggers and ruling out sleep apnoea in adults", "Specialist assessment and medication for REM sleep behaviour disorder, prescribed and monitored by a doctor"],
  "self_help_that_supports_care": ["Enough sleep; sleep loss is the biggest trigger", "Bedroom safety: locks, alarms on doors, nothing sharp nearby", "Less alcohol and no screens late", "For partners: sleep separately if there's a risk of injury, without shame"],
  "guideline_refs": ["src-nhs-sleepwalking"]},
 "If sleep episodes are causing injury, happening most nights, starting in adulthood, or involve acting out dreams, ask a doctor for a sleep-clinic referral. Childhood sleepwalking and terrors usually need only reassurance unless they're frequent or dangerous.",
 "Nightmares, which wake you with a clear memory, are a different condition. Seizures during sleep and confusion from medication or apnoea need medical assessment. Talking in your sleep is normal.",
 "Children grow out of sleepwalking and terrors. Adults with parasomnias, including REM behaviour disorder, can sleep safely with the right plan.",
 ["nightmare-disorder", "breathing-related-sleep-disorders", "parkinsons-disease-neurocognitive-disorder", "lewy-body-neurocognitive-disorder", "insomnia-disorder"],
 ["night-terrors", "sleep-paralysis", "sleep-hygiene"],
 ["sleep-disorders-australia", "reddit-r-insomnia"],
 ("Soft line illustration of a parent sitting calmly beside a child's bed at night with a small nightlight, a safety gate visible at the top of the stairs. Pastel indigo and peach.", "A parent sits calmly beside a child's bed at night with a small nightlight, a safety gate at the top of the stairs."),
 [DSM_S, src("src-nhs-sleepwalking", "Sleepwalking", "NHS", "https://www.nhs.uk/conditions/sleepwalking/", note="Not opened.")],
 qs=["Find primary prevalence sources.", "Add an RBD-specific patient community after verification."],
 young="Sleep terrors peak around ages 3 to 7 and sleepwalking around 8 to 12. They run in families and are triggered by tiredness, illness, and stress. Most children outgrow them without treatment.",
 subs=[{"title": "NREM sleep arousal disorders", "icd10cm_code": "F51.3 (sleepwalking) / F51.4 (sleep terror)", "text": "Happen in deep sleep, usually in the first third of the night, with little or no memory."},
       {"title": "REM sleep behaviour disorder", "icd10cm_code": "G47.52", "text": "Dream enactment in REM sleep, usually later in the night, with the person often remembering the dream. Needs specialist assessment."}]))

CARDS.append(S("nightmare-disorder", "Nightmare Disorder", "When bad dreams keep breaking your sleep", ["chronic nightmares", "recurrent nightmares"], "F51.5",
 "Repeated, vivid, frightening dreams that wake you and cause real distress or disrupt sleep and daily life.",
 "Everyone has nightmares now and then. Nightmare disorder is when they come often, are intensely distressing, wake you fully with a clear memory, and leave you dreading sleep or exhausted by day. They're especially common after trauma and alongside PTSD, anxiety, and depression, and some medications can trigger them. The good news: nightmares respond well to a specific, surprisingly simple therapy that teaches you to rewrite the dream.",
 ["I'd wake up screaming three nights a week. I started staying up to avoid it.", "After the assault the dreams were worse than the days.", "Imagery rehearsal felt silly. I rewrote the ending twenty times. The nightmare stopped coming."],
 ["Frequent, vivid, frightening dreams, often about danger or survival", "Waking fully and remembering the dream clearly", "Hard to get back to sleep; dread of going to bed", "Daytime tiredness, anxiety, low mood, or trouble concentrating", "Not explained by a substance, medication, or another condition"],
 [{"myth": "Nightmares are just dreams; they can't be treated.", "fact": "Imagery rehearsal therapy, which involves rewriting the nightmare while awake, reduces nightmares in most people within weeks."},
  {"myth": "Nightmares and night terrors are the same.", "fact": "Night terrors happen in deep sleep with no memory; nightmares happen in dreaming sleep and are remembered vividly."},
  {"myth": "Only children have nightmares.", "fact": "Nightmare disorder affects adults too, especially after trauma. Frequent adult nightmares deserve attention."}],
 {"plain": "Occasional nightmares are universal. Frequent nightmares affect about 1 to 2 in 100 adults, far more among people with PTSD.", "figure": "About 6% of adults report monthly nightmares and 1–2% frequent nightmares (population surveys); much higher with PTSD", "source_ref": "src-euro-sleep", "note": "Secondary source; needs the primary survey."},
 {"plain_summary": "Imagery rehearsal therapy, in which you write down the nightmare, change it into something less frightening, and rehearse the new version while awake, is the first-line treatment and works for trauma-related and other nightmares. CBT for insomnia helps the sleep that's been disrupted. For PTSD-related nightmares, trauma-focused therapy and, in some cases, medication prescribed and monitored by a doctor, help. Reviewing medicines that can cause nightmares is part of care.",
  "evidence_based_options": ["Imagery rehearsal therapy", "CBT for insomnia and trauma-focused therapy where relevant", "Review of medications that trigger nightmares", "Medication for PTSD-related nightmares in some cases, prescribed and monitored by a doctor"],
  "self_help_that_supports_care": ["Writing the nightmare down and changing the ending, then rehearsing it daily", "A calming routine before bed; no frightening content late", "Getting up briefly and grounding after a nightmare, then returning", "Treating the daytime anxiety or trauma underneath"],
  "guideline_refs": ["src-aasm-nightmare"]},
 "If nightmares are frequent, wake you most weeks, or make you dread sleep, ask a doctor or therapist about imagery rehearsal therapy, especially after a trauma. Nightmares with new medication are worth reporting.",
 "Occasional nightmares after a scary film or a stressful day aren't a disorder. Sleep terrors, with no memory, are a different condition. Nightmares as part of PTSD are treated within PTSD care.",
 "Nightmares can be rewritten. Most people who try imagery rehearsal get their nights back within a few weeks.",
 ["posttraumatic-stress-disorder", "parasomnias", "insomnia-disorder", "generalized-anxiety-disorder", "acute-stress-disorder"],
 ["trauma", "grounding", "cbt-i", "sleep-hygiene"],
 ["reddit-r-cptsd", "reddit-r-insomnia", "sleep-disorders-australia"],
 ("Soft line illustration of a person at a desk in daylight writing in a notebook, crossing out a line and writing a new one, a plant and a mug beside them. Pastel indigo and mint.", "A person writes in a notebook in daylight, crossing out a line and writing a new one."),
 [DSM_S, src("src-aasm-nightmare", "Position paper for the treatment of nightmare disorder in adults", "American Academy of Sleep Medicine", "https://aasm.org/clinical-resources/practice-standards/practice-guidelines/", 2018, note="Not opened; listing URL."), EURO],
 qs=["Find the primary prevalence survey."],
 young="Nightmares are common in children aged 3 to 6 and usually fade. Frequent, distressing nightmares in a child, especially after a frightening event, deserve gentle attention and sometimes child-adapted imagery rehearsal.",
 sens="elevated", notes=["Trauma content referenced without detail."]))

CARDS.append(S("restless-legs-syndrome", "Restless Legs Syndrome", "An unbearable urge to move your legs at night", ["RLS", "Willis-Ekbom disease"], "G25.81",
 "An uncomfortable urge to move the legs, worse in the evening and at rest, relieved by movement, that disrupts sleep.",
 "Restless legs syndrome is a neurological condition, not a psychological one, but it belongs here because it wrecks sleep. People feel a creeping, crawling, aching, or 'electric' urge to move their legs, worst in the evening and when sitting or lying still, eased for a moment by moving. It makes falling asleep hard and causes exhaustion and low mood. It's linked to iron levels and sometimes pregnancy, kidney disease, or certain medicines. It's common and treatable.",
 ["It's not pain exactly. It's like ants under the skin and the only relief is to walk.", "I'd kick all night. My wife moved to the spare room. Iron tablets changed my life.", "Long flights and cinemas were impossible. Now I plan around it, and the medication works."],
 ["An urge to move the legs, with uncomfortable sensations", "Worse in the evening or at night, and when resting", "Relieved, at least briefly, by moving", "At least three times a week for three months or more", "Trouble falling or staying asleep, daytime tiredness, low mood"],
 [{"myth": "It's all in your head, or just fidgeting.", "fact": "RLS is a recognized neurological condition with a clear pattern and effective treatments."},
  {"myth": "Nothing helps except getting up and walking.", "fact": "Treating low iron, adjusting medicines that worsen it, and specific medications, prescribed and monitored by a doctor, help most people."},
  {"myth": "It only affects old people.", "fact": "RLS can start in childhood, where it's often called 'growing pains', and it's common in pregnancy."}],
 {"plain": "About 2 to 3 in 100 adults have restless legs syndrome severe enough to need treatment, women more than men, and it becomes more common with age.", "figure": "About 1.6%–3% of adults meet criteria (estimates vary by country and method)", "source_ref": "src-euro-sleep"},
 {"plain_summary": "The first step is checking iron levels and treating low iron, which often helps. Medicines that worsen RLS, including some antidepressants and antihistamines, are reviewed. For ongoing symptoms, specific medications, prescribed and monitored by a doctor, are effective, with newer guidelines favouring certain types over older ones because of long-term side effects. Regular sleep, moderate exercise, and avoiding caffeine and alcohol late help.",
  "evidence_based_options": ["Checking and treating iron deficiency", "Reviewing medications that worsen RLS", "RLS medications, prescribed and monitored by a doctor, following current guidelines", "Sleep routine, exercise, and avoiding evening caffeine and alcohol"],
  "self_help_that_supports_care": ["Asking for an iron (ferritin) blood test", "Moderate exercise earlier in the day, not late", "Warm baths, leg massage, or stretching in the evening", "Keeping a symptom diary to show the pattern"],
  "guideline_refs": ["src-aasm-rls"]},
 "If leg discomfort and the urge to move are disrupting your sleep several nights a week, ask a doctor and request an iron check. Mention any medicines you take, including antidepressants.",
 "Leg cramps, positional discomfort, or nervous fidgeting aren't RLS. Akathisia, a restlessness caused by some psychiatric medicines, feels similar and is covered on the medication side-effects card.",
 "RLS is very treatable. Many people get their evenings and nights back with an iron supplement or one medication.",
 ["insomnia-disorder", "medication-induced-movement-disorders", "major-depressive-disorder", "adhd"],
 ["sleep-hygiene", "side-effects"],
 ["sleep-disorders-australia", "reddit-r-insomnia"],
 ("Soft line illustration of a person stretching their legs on a yoga mat in a calm evening living room, a warm lamp, a cup of herbal tea. Pastel indigo and sage.", "A person stretches on a yoga mat in a calm evening living room beside a warm lamp."),
 [DSM_S, EURO, src("src-aasm-rls", "Treatment of restless legs syndrome and periodic limb movement disorder: an AASM clinical practice guideline", "American Academy of Sleep Medicine", "https://aasm.org/clinical-resources/practice-standards/practice-guidelines/", 2024, note="Not opened; listing URL."), src("src-rlsf", "Restless Legs Syndrome Foundation", "RLS Foundation", "https://www.rls.org/", note="Not opened.")],
 qs=["Verify the RLS Foundation support groups and add.", "Find a primary prevalence source."],
 young="RLS in children is often misread as growing pains or ADHD-type fidgeting. A family history and the evening pattern are clues, and iron is often low."))
